import { readSkyPhotoExif, type SkyPhotoExif } from "@/lib/sky-photo-exif"
import { findClouds, findWindows } from "@/lib/sky-photo-features"
import { findSkySteps, skyMaskSize, type SkyMask } from "@/lib/sky-photo-mask"

/** A photo ready to have its sky replaced: its upright size, its sky and where its horizon most likely is. */
type SkyPhotoAnalysis = {
  width: number
  height: number
  /** Width over height, after the EXIF orientation. */
  aspect: number
  exif: SkyPhotoExif
  mask: SkyMask
  /** The sky as a canvas at the analysis size: opaque where it is sky, feathered at the edges. */
  sky: HTMLCanvasElement
  /** An object URL of a PNG that is opaque where the photo is not sky, for `mask-image`. Freed by `dispose`. */
  foregroundUrl: string
  /** With `clouds`, object URLs of the photo's clouds for `mask-image`: how much cloud covers each pixel, and how lit. */
  clouds: { shadeUrl: string; lightUrl: string } | undefined
  /** With `windows`, an object URL of the window panes to light at night, for `mask-image`. */
  windowsUrl: string | undefined
  /** How long the sky finder took, in ms. */
  analysisMs: number
  /** Frees every object URL above. */
  dispose: () => void
}

type SkyPhotoOptions = {
  /** An image to use as the sky mask instead of finding it: white is sky, black is the foreground. */
  skyMask?: string | Blob | undefined
  /** Also finds the photo's own clouds (`findClouds`). */
  clouds?: boolean | undefined
  /** Also finds windows to light at night (`findWindows`), lighting a seeded share of them. */
  windows?: boolean | undefined
  signal?: AbortSignal | undefined
}

const nextTask = () => new Promise<void>((resolve) => setTimeout(resolve, 0))

const sliceMs = 6

// Perf: the finder takes hundreds of ms on a 1024 px photo on a slow device; run in slices of a few ms, it holds no
// frame or key press for longer than one slice.
async function findSkyYielding(pixels: ImageData, signal: AbortSignal | undefined) {
  const steps = findSkySteps(pixels)
  let until = performance.now() + sliceMs
  for (;;) {
    const step = steps.next()
    if (step.done) return step.value
    if (performance.now() < until) continue
    // oxlint-disable-next-line no-await-in-loop -- each slice waits for the page to take its turn before the next one
    await nextTask()
    signal?.throwIfAborted()
    until = performance.now() + sliceMs
  }
}

async function blobOf(source: string | Blob, signal: AbortSignal | undefined) {
  if (typeof source !== "string") return source
  const response = await fetch(source, { signal })
  if (!response.ok) throw new Error(`The photo couldn't be read: ${String(response.status)} ${response.statusText}`)
  return response.blob()
}

function canvasOf(width: number, height: number) {
  const canvas = document.createElement("canvas")
  canvas.width = width
  canvas.height = height
  return canvas
}

function drawScaled(bitmap: ImageBitmap, width: number, height: number) {
  const canvas = canvasOf(width, height)
  const context = canvas.getContext("2d", { willReadFrequently: true })
  if (!context) throw new Error("The photo couldn't be read: no 2D canvas")
  context.imageSmoothingQuality = "high"
  context.drawImage(bitmap, 0, 0, width, height)
  return context.getImageData(0, 0, width, height)
}

function maskFromImage(image: ImageData): SkyMask {
  const { width, height, data } = image
  const alpha = new Uint8ClampedArray(width * height)
  for (let index = 0; index < alpha.length; index++) {
    const at = index * 4
    alpha[index] = Math.round(0.299 * data[at]! + 0.587 * data[at + 1]! + 0.114 * data[at + 2]!)
  }
  const skyline = new Float32Array(width)
  for (let x = 0; x < width; x++) {
    let row = 0
    while (row < height && alpha[row * width + x]! >= 128) row++
    skyline[x] = row / height
  }
  const sorted = [...skyline].toSorted((a, b) => a - b)
  return { width, height, alpha, skyline, horizon: sorted[Math.floor(sorted.length * 0.85)] ?? 0.5 }
}

// Spec: the foreground's edge is pulled in a little past the feather's middle, so the old sky's light rim around buildings
// doesn't show against the new sky.
const foregroundAlpha = (sky: number) => Math.max(0, Math.min(255, Math.round((255 - sky) * 1.6 - 115)))

function alphaCanvas(width: number, height: number, alpha: Uint8ClampedArray, map: (value: number) => number) {
  const canvas = canvasOf(width, height)
  const context = canvas.getContext("2d")
  if (!context) throw new Error("The photo couldn't be read: no 2D canvas")
  const image = context.createImageData(width, height)
  for (let index = 0; index < alpha.length; index++) image.data[index * 4 + 3] = map(alpha[index]!)
  context.putImageData(image, 0, 0)
  return canvas
}

const same = (value: number) => value

async function alphaUrl(width: number, height: number, alpha: Uint8ClampedArray) {
  return URL.createObjectURL(await pngOf(alphaCanvas(width, height, alpha, same)))
}

const pngOf = (canvas: HTMLCanvasElement) =>
  new Promise<Blob>((resolve, reject) =>
    canvas.toBlob(
      (blob) => (blob ? resolve(blob) : reject(new Error("The sky mask couldn't be encoded"))),
      "image/png",
    ),
  )

/**
 * Reads a photo locally (an object URL, a same-origin URL or a `Blob`; nothing is uploaded), its EXIF, and finds its
 * sky, or takes `skyMask` for it. A cross-origin URL needs CORS, since the finder reads its pixels.
 */
async function analyzeSkyPhoto(
  source: string | Blob,
  { skyMask, clouds: wantClouds = false, windows: wantWindows = false, signal }: SkyPhotoOptions = {},
): Promise<SkyPhotoAnalysis> {
  const blob = await blobOf(source, signal)
  const exif = readSkyPhotoExif(await blob.slice(0, 131_072).arrayBuffer())
  const bitmap = await createImageBitmap(blob, { imageOrientation: "from-image" })
  const { width, height } = bitmap
  const scale = Math.min(1, skyMaskSize / Math.max(width, height))
  const small = { width: Math.max(1, Math.round(width * scale)), height: Math.max(1, Math.round(height * scale)) }
  const started = performance.now()
  const pixels = drawScaled(bitmap, small.width, small.height)
  let mask: SkyMask
  if (skyMask === undefined) {
    mask = await findSkyYielding(pixels, signal)
  } else {
    const maskBitmap = await createImageBitmap(await blobOf(skyMask, signal))
    mask = maskFromImage(drawScaled(maskBitmap, small.width, small.height))
    maskBitmap.close()
  }
  const analysisMs = performance.now() - started
  bitmap.close()
  signal?.throwIfAborted()
  const sky = alphaCanvas(mask.width, mask.height, mask.alpha, same)
  const foregroundUrl = URL.createObjectURL(
    await pngOf(alphaCanvas(mask.width, mask.height, mask.alpha, foregroundAlpha)),
  )
  let clouds: SkyPhotoAnalysis["clouds"]
  if (wantClouds) {
    await nextTask()
    const found = findClouds(pixels, mask)
    clouds = {
      shadeUrl: await alphaUrl(found.width, found.height, found.shade),
      lightUrl: await alphaUrl(found.width, found.height, found.light),
    }
  }
  let windowsUrl: string | undefined
  if (wantWindows) {
    await nextTask()
    const found = findWindows(pixels, mask)
    if (found.lit > 0) windowsUrl = await alphaUrl(found.width, found.height, found.glow)
  }
  const urls = [foregroundUrl, clouds?.shadeUrl, clouds?.lightUrl, windowsUrl]
  return {
    width,
    height,
    aspect: width / height,
    exif,
    mask,
    sky,
    foregroundUrl,
    clouds,
    windowsUrl,
    analysisMs,
    dispose: () => {
      for (const url of urls) if (url) URL.revokeObjectURL(url)
    },
  }
}

export { analyzeSkyPhoto }
export type { SkyPhotoAnalysis, SkyPhotoOptions }

/** What a photo's EXIF says about where and how it was taken. Every field is missing when the file doesn't carry it. */
type SkyPhotoExif = {
  /** EXIF orientation, 1 to 8; browsers already draw the image upright. */
  orientation?: number
  /** The capture time as the camera's clock showed it, `"2025-04-14T06:43:28"`, with no zone. */
  capturedAt?: string
  /** The clock's offset from UTC at capture, `"+08:00"`, when the camera wrote one. */
  utcOffset?: string
  latitude?: number
  longitude?: number
  /** The compass heading the lens pointed at, in degrees from true or magnetic north (see `headingReference`). */
  heading?: number
  headingReference?: "true" | "magnetic"
  /** The lens's focal length in millimetres. */
  focalLength?: number
  /** The focal length a full-frame (36 × 24 mm) camera would need for the same view. */
  focalLength35mm?: number
  /** Pixel size the camera recorded, before any orientation. */
  width?: number
  height?: number
}

const tags = {
  orientation: 0x0112,
  exifPointer: 0x8769,
  gpsPointer: 0x8825,
  dateTimeOriginal: 0x9003,
  offsetTimeOriginal: 0x9011,
  focalLength: 0x920a,
  focalLength35mm: 0xa405,
  pixelWidth: 0xa002,
  pixelHeight: 0xa003,
  gpsLatitudeRef: 0x0001,
  gpsLatitude: 0x0002,
  gpsLongitudeRef: 0x0003,
  gpsLongitude: 0x0004,
  gpsImgDirectionRef: 0x0010,
  gpsImgDirection: 0x0011,
} as const

const typeSizes: Record<number, number> = { 1: 1, 2: 1, 3: 2, 4: 4, 5: 8, 7: 1, 9: 4, 10: 8 }

type Entry = { type: number; count: number; offset: number }

class TiffReader {
  readonly view: DataView
  readonly start: number
  readonly little: boolean

  constructor(view: DataView, start: number) {
    this.view = view
    this.start = start
    this.little = view.getUint16(start) === 0x4949
  }

  u16(at: number) {
    return this.view.getUint16(this.start + at, this.little)
  }

  u32(at: number) {
    return this.view.getUint32(this.start + at, this.little)
  }

  inBounds(at: number, size: number) {
    return at >= 0 && this.start + at + size <= this.view.byteLength
  }

  directory(at: number): Map<number, Entry> {
    const entries = new Map<number, Entry>()
    if (!this.inBounds(at, 2)) return entries
    const count = this.u16(at)
    for (let index = 0; index < count; index++) {
      const entry = at + 2 + index * 12
      if (!this.inBounds(entry, 12)) break
      const type = this.u16(entry + 2)
      const valueCount = this.u32(entry + 4)
      const size = (typeSizes[type] ?? 0) * valueCount
      entries.set(this.u16(entry), { type, count: valueCount, offset: size <= 4 ? entry + 8 : this.u32(entry + 8) })
    }
    return entries
  }

  numbers(entry: Entry | undefined): number[] {
    if (!entry) return []
    const size = typeSizes[entry.type] ?? 0
    if (size === 0 || !this.inBounds(entry.offset, size * entry.count)) return []
    const values: number[] = []
    for (let index = 0; index < entry.count; index++) {
      const at = entry.offset + index * size
      if (entry.type === 3) values.push(this.u16(at))
      else if (entry.type === 4) values.push(this.u32(at))
      else if (entry.type === 9) values.push(this.view.getInt32(this.start + at, this.little))
      else if (entry.type === 5 || entry.type === 10) {
        const signed = entry.type === 10
        const numerator = signed ? this.view.getInt32(this.start + at, this.little) : this.u32(at)
        const denominator = signed ? this.view.getInt32(this.start + at + 4, this.little) : this.u32(at + 4)
        values.push(denominator === 0 ? Number.NaN : numerator / denominator)
      } else values.push(this.view.getUint8(this.start + at))
    }
    return values
  }

  text(entry: Entry | undefined) {
    if (entry?.type !== 2 || !this.inBounds(entry.offset, entry.count)) return undefined
    let text = ""
    for (let index = 0; index < entry.count; index++) {
      const code = this.view.getUint8(this.start + entry.offset + index)
      if (code === 0) break
      text += String.fromCharCode(code)
    }
    return text.trim() || undefined
  }
}

const finite = (value: number | undefined) => (value !== undefined && Number.isFinite(value) ? value : undefined)

function degreesOf(parts: number[], reference: string | undefined) {
  if (parts.length < 3 || !parts.every(Number.isFinite)) return undefined
  const degrees = parts[0]! + parts[1]! / 60 + parts[2]! / 3600
  return reference === "S" || reference === "W" ? -degrees : degrees
}

const capturedPattern = /^(\d{4}):(\d{2}):(\d{2}) (\d{2}):(\d{2}):(\d{2})$/

function readTiff(view: DataView, start: number): SkyPhotoExif {
  const tiff = new TiffReader(view, start)
  if (tiff.u16(2) !== 42) return {}
  const main = tiff.directory(tiff.u32(4))
  const exifAt = tiff.numbers(main.get(tags.exifPointer))[0]
  const gpsAt = tiff.numbers(main.get(tags.gpsPointer))[0]
  const exif = exifAt === undefined ? new Map<number, Entry>() : tiff.directory(exifAt)
  const gps = gpsAt === undefined ? new Map<number, Entry>() : tiff.directory(gpsAt)
  const result: SkyPhotoExif = {}

  const orientation = tiff.numbers(main.get(tags.orientation))[0]
  if (orientation !== undefined && orientation >= 1 && orientation <= 8) result.orientation = orientation
  const captured = capturedPattern.exec(tiff.text(exif.get(tags.dateTimeOriginal)) ?? "")
  if (captured) {
    const [, year, month, day, hours, minutes, seconds] = captured
    result.capturedAt = `${year!}-${month!}-${day!}T${hours!}:${minutes!}:${seconds!}`
  }
  const offset = tiff.text(exif.get(tags.offsetTimeOriginal))
  if (offset && /^[+-]\d{2}:\d{2}$/.test(offset)) result.utcOffset = offset
  const focalLength = finite(tiff.numbers(exif.get(tags.focalLength))[0])
  if (focalLength && focalLength > 0) result.focalLength = focalLength
  const focalLength35mm = finite(tiff.numbers(exif.get(tags.focalLength35mm))[0])
  if (focalLength35mm && focalLength35mm > 0) result.focalLength35mm = focalLength35mm
  const width = tiff.numbers(exif.get(tags.pixelWidth))[0]
  const height = tiff.numbers(exif.get(tags.pixelHeight))[0]
  if (width && height) {
    result.width = width
    result.height = height
  }

  const latitude = degreesOf(tiff.numbers(gps.get(tags.gpsLatitude)), tiff.text(gps.get(tags.gpsLatitudeRef)))
  const longitude = degreesOf(tiff.numbers(gps.get(tags.gpsLongitude)), tiff.text(gps.get(tags.gpsLongitudeRef)))
  if (latitude !== undefined && longitude !== undefined && Math.abs(latitude) <= 90 && Math.abs(longitude) <= 180) {
    result.latitude = latitude
    result.longitude = longitude
  }
  const heading = finite(tiff.numbers(gps.get(tags.gpsImgDirection))[0])
  if (heading !== undefined && heading >= 0 && heading <= 360) {
    result.heading = heading % 360
    result.headingReference = tiff.text(gps.get(tags.gpsImgDirectionRef)) === "M" ? "magnetic" : "true"
  }
  return result
}

const exifHeader = 0x45786966

/**
 * Reads a JPEG's EXIF (its APP1 segment) or a bare TIFF. Unknown, broken or missing data gives an empty object; it
 * never throws. The first 128 KB of a file are enough: cameras write EXIF before the image.
 */
function readSkyPhotoExif(bytes: ArrayBuffer | ArrayBufferView): SkyPhotoExif {
  const view = ArrayBuffer.isView(bytes)
    ? new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength)
    : new DataView(bytes)
  try {
    if (view.byteLength < 8) return {}
    const first = view.getUint16(0)
    if (first === 0x4949 || first === 0x4d4d) return readTiff(view, 0)
    if (first !== 0xffd8) return {}
    let at = 2
    while (at + 4 <= view.byteLength) {
      const marker = view.getUint16(at)
      if ((marker & 0xff00) !== 0xff00 || marker === 0xffda || marker === 0xffd9) return {}
      const length = view.getUint16(at + 2)
      if (marker === 0xffe1 && at + 10 <= view.byteLength && view.getUint32(at + 4) === exifHeader) {
        return readTiff(view, at + 10)
      }
      at += 2 + length
    }
    return {}
  } catch {
    return {}
  }
}

/** Reads the EXIF of a `File` or `Blob` from its first 128 KB. */
async function readSkyPhotoExifFrom(blob: Blob): Promise<SkyPhotoExif> {
  return readSkyPhotoExif(await blob.slice(0, 131_072).arrayBuffer())
}

export { readSkyPhotoExif, readSkyPhotoExifFrom }
export type { SkyPhotoExif }

// Perf: a classical skyline finder, no model to download. It runs on a copy of the photo at most 1024 pixels on its long
// side: a per-pixel sky likelihood from colour, brightness and texture, then one skyline per column by dynamic
// programming, in O(width × height).

/** A sky mask over a downscaled photo: `alpha` is 255 where it is sky, feathered at the edges. */
type SkyMask = {
  width: number
  height: number
  alpha: Uint8ClampedArray
  /** The skyline's row in each column, from 0 (top) to 1 (bottom). */
  skyline: Float32Array
  /** A default horizon from 0 to 1: the skyline's lowest band, where the farthest buildings meet the sky. */
  horizon: number
}

type Pixels = { data: Uint8ClampedArray; width: number; height: number }

/** The longest side the finder works at; a larger photo is scaled down to it first. */
const skyMaskSize = 1024

const clamp01 = (value: number) => (value < 0 ? 0 : value > 1 ? 1 : value)

type Steps<T> = Generator<void, T, void>

const rowsPerStep = 8
const columnsPerStep = 16

function finished<T>(steps: Steps<T>): T {
  for (;;) {
    const step = steps.next()
    if (step.done) return step.value
  }
}

function luminance({ data, width, height }: Pixels) {
  const result = new Float32Array(width * height)
  for (let index = 0; index < result.length; index++) {
    const at = index * 4
    result[index] = (0.299 * data[at]! + 0.587 * data[at + 1]! + 0.114 * data[at + 2]!) / 255
  }
  return result
}

function* boxBlur(source: Float32Array, width: number, height: number, radius: number): Steps<Float32Array> {
  const across = new Float32Array(source.length)
  const result = new Float32Array(source.length)
  const span = radius * 2 + 1
  for (let y = 0; y < height; y++) {
    if (y % rowsPerStep === 0) yield
    let sum = 0
    for (let x = -radius; x <= radius; x++) sum += source[y * width + Math.min(width - 1, Math.max(0, x))]!
    for (let x = 0; x < width; x++) {
      across[y * width + x] = sum / span
      sum += source[y * width + Math.min(width - 1, x + radius + 1)]! - source[y * width + Math.max(0, x - radius)]!
    }
  }
  for (let x = 0; x < width; x++) {
    if (x % columnsPerStep === 0) yield
    let sum = 0
    for (let y = -radius; y <= radius; y++) sum += across[Math.min(height - 1, Math.max(0, y)) * width + x]!
    for (let y = 0; y < height; y++) {
      result[y * width + x] = sum / span
      sum += across[Math.min(height - 1, y + radius + 1) * width + x]! - across[Math.max(0, y - radius) * width + x]!
    }
  }
  return result
}

function blurAcross(source: Float32Array, width: number, height: number, radius: number) {
  const result = new Float32Array(source.length)
  const span = radius * 2 + 1
  for (let y = 0; y < height; y++) {
    let sum = 0
    for (let x = -radius; x <= radius; x++) sum += source[y * width + Math.min(width - 1, Math.max(0, x))]!
    for (let x = 0; x < width; x++) {
      result[y * width + x] = sum / span
      sum += source[y * width + Math.min(width - 1, x + radius + 1)]! - source[y * width + Math.max(0, x - radius)]!
    }
  }
  return result
}

// Spec: a roofline or the top of a blank wall is a crisp edge that runs straight for many pixels; a cloud's edge is soft
// and wavy. Averaged along the row, only the straight ones stay strong, and the skyline is pulled onto them.
function straightEdges(vertical: Float32Array, width: number, height: number) {
  const along = blurAcross(vertical, width, height, Math.max(4, Math.round(width / 80)))
  const result = new Float32Array(along.length)
  for (let index = 0; index < along.length; index++) result[index] = clamp01((along[index]! - 0.1) * 4)
  return result
}

function* gradients(light: Float32Array, width: number, height: number) {
  const magnitude = new Float32Array(light.length)
  const vertical = new Float32Array(light.length)
  for (let y = 1; y < height - 1; y++) {
    if (y % rowsPerStep === 0) yield
    for (let x = 1; x < width - 1; x++) {
      const at = y * width + x
      const gx =
        light[at - width + 1]! +
        2 * light[at + 1]! +
        light[at + width + 1]! -
        light[at - width - 1]! -
        2 * light[at - 1]! -
        light[at + width - 1]!
      const gy =
        light[at + width - 1]! +
        2 * light[at + width]! +
        light[at + width + 1]! -
        light[at - width - 1]! -
        2 * light[at - width]! -
        light[at - width + 1]!
      magnitude[at] = Math.hypot(gx, gy)
      vertical[at] = Math.abs(gy)
    }
  }
  return { magnitude, vertical }
}

type Rgb = [number, number, number]

function skyColours({ data, width, height }: Pixels): Rgb[] {
  const rows = Math.max(1, Math.round(height * 0.06))
  const bins = 8
  const colours: Rgb[] = []
  for (let bin = 0; bin < bins; bin++) {
    const from = Math.floor((bin * width) / bins)
    const to = Math.floor(((bin + 1) * width) / bins)
    let red = 0
    let green = 0
    let blue = 0
    let count = 0
    for (let y = 0; y < rows; y++) {
      for (let x = from; x < to; x++) {
        const at = (y * width + x) * 4
        red += data[at]!
        green += data[at + 1]!
        blue += data[at + 2]!
        count++
      }
    }
    if (count > 0) colours.push([red / count / 255, green / count / 255, blue / count / 255])
  }
  return colours
}

function coloursAbove({ data, width }: Pixels, skyline: Int32Array): Rgb[] {
  const bands = 6
  const columns = 4
  const colours: Rgb[] = []
  for (let column = 0; column < columns; column++) {
    const from = Math.floor((column * width) / columns)
    const to = Math.floor(((column + 1) * width) / columns)
    for (let band = 0; band < bands; band++) {
      let red = 0
      let green = 0
      let blue = 0
      let count = 0
      for (let x = from; x < to; x++) {
        const line = skyline[x]!
        const top = Math.floor((band * line) / bands)
        const bottom = Math.floor(((band + 1) * line) / bands) - (band === bands - 1 ? 2 : 0)
        for (let y = top; y < bottom; y++) {
          const at = (y * width + x) * 4
          red += data[at]!
          green += data[at + 1]!
          blue += data[at + 2]!
          count++
        }
      }
      if (count > 8) colours.push([red / count / 255, green / count / 255, blue / count / 255])
    }
  }
  return colours
}

function* skyLikelihoodSteps(pixels: Pixels, known?: Rgb[]) {
  const { data, width, height } = pixels
  const light = luminance(pixels)
  yield
  const { magnitude, vertical } = yield* gradients(light, width, height)
  const texture = yield* boxBlur(magnitude, width, height, 2)
  const crisp = yield* boxBlur(magnitude, width, height, 1)
  const colours = known && known.length > 0 ? known : skyColours(pixels)
  const likelihood = new Float32Array(width * height)
  const colour = new Float32Array(width * height)
  const structure = new Float32Array(width * height)
  for (let index = 0; index < likelihood.length; index++) {
    if (index % (width * rowsPerStep) === 0) yield
    const at = index * 4
    const red = data[at]! / 255
    const green = data[at + 1]! / 255
    const blue = data[at + 2]! / 255
    let nearest = Infinity
    for (const [r, g, b] of colours) nearest = Math.min(nearest, (red - r) ** 2 + (green - g) ** 2 + (blue - b) ** 2)
    const similar = Math.exp(-nearest / 0.02)
    const max = Math.max(red, green, blue)
    const saturation = max === 0 ? 0 : (max - Math.min(red, green, blue)) / max
    const blueSky = clamp01((blue - red) * 3 + 0.2) * clamp01(blue * 1.4 - 0.2)
    const greyCloud =
      clamp01((light[index]! - 0.3) * 2.2) * clamp01(1 - saturation * 3.5) * clamp01((blue - red) * 6 + 0.3)
    const whiteCloud = clamp01((light[index]! - 0.72) * 4) * clamp01(1 - saturation * 4)
    const cloud = Math.max(greyCloud, whiteCloud)
    const hardEdge = clamp01((crisp[index]! - 0.18) * 5)
    const smooth = clamp01(1 - texture[index]! * 4) * (1 - hardEdge)
    structure[index] = clamp01((crisp[index]! - strongEdge) * 6)
    colour[index] = Math.min(similar, blueSky)
    const upper = clamp01(1 - (2 * Math.floor(index / width)) / height)
    likelihood[index] = clamp01(
      Math.sqrt(Math.max(similar, blueSky, cloud) * (0.3 + 0.7 * smooth)) + 0.2 * upper * smooth,
    )
  }
  return { likelihood, colour, structure, vertical, light }
}

/**
 * How likely each pixel is sky, from 0 to 1: close to known sky colours (the top rows by default), bright or blue,
 * smooth, and higher up.
 */
const skyLikelihood = (pixels: Pixels, known?: Rgb[]) => finished(skyLikelihoodSteps(pixels, known))

const smoothnessPerRow = 0.6
const jumpRows = 0.12

function* skylineByDynamicProgramming(
  likelihood: Float32Array,
  edges: Float32Array,
  straight: Float32Array,
  width: number,
  height: number,
): Steps<Int32Array> {
  const straightPull = height * 0.04
  const cost = new Float32Array(height + 1)
  const previous = new Float32Array(height + 1)
  const current = new Float32Array(height + 1)
  const from = new Int32Array(width * (height + 1))
  const jump = Math.max(2, Math.round(height * jumpRows))
  const columnCost = (x: number) => {
    let ground = 0
    for (let y = 0; y < height; y++) ground += likelihood[y * width + x]!
    let sky = 0
    cost[0] = ground
    for (let row = 1; row <= height; row++) {
      const value = likelihood[(row - 1) * width + x]!
      sky += 1 - value
      ground -= value
      const edge = row < height ? edges[row * width + x]! + straightPull * straight[row * width + x]! : 0
      cost[row] = sky + ground - edge
    }
  }
  columnCost(0)
  previous.set(cost)
  for (let x = 1; x < width; x++) {
    if (x % columnsPerStep === 0) yield
    columnCost(x)
    const best = new Float32Array(previous)
    const argument = new Int32Array(height + 1).map((_, row) => row)
    for (let row = 1; row <= height; row++) {
      if (best[row - 1]! + smoothnessPerRow < best[row]!) {
        best[row] = best[row - 1]! + smoothnessPerRow
        argument[row] = argument[row - 1]!
      }
    }
    for (let row = height - 1; row >= 0; row--) {
      if (best[row + 1]! + smoothnessPerRow < best[row]!) {
        best[row] = best[row + 1]! + smoothnessPerRow
        argument[row] = argument[row + 1]!
      }
    }
    let lowest = 0
    for (let row = 1; row <= height; row++) if (previous[row]! < previous[lowest]!) lowest = row
    const jumpCost = previous[lowest]! + smoothnessPerRow * jump
    for (let row = 0; row <= height; row++) {
      const viaJump = best[row]! > jumpCost
      current[row] = cost[row]! + (viaJump ? jumpCost : best[row]!)
      from[x * (height + 1) + row] = viaJump ? lowest : argument[row]!
    }
    previous.set(current)
  }
  const skyline = new Int32Array(width)
  let row = 0
  for (let candidate = 1; candidate <= height; candidate++) if (previous[candidate]! < previous[row]!) row = candidate
  for (let x = width - 1; x >= 0; x--) {
    skyline[x] = row
    if (x > 0) row = from[x * (height + 1) + row]!
  }
  return skyline
}

// Spec: sky seen through a gap below the skyline must match the sky's own colours and be blue, and sit above the
// skyline's lowest band, so a blue car or a sign in the street never turns into sky.
const holeColour = 0.8
const foregroundLikelihood = 0.4
const featherRadius = 1

function slidingExtreme(values: Int32Array, radius: number, pick: (a: number, b: number) => number) {
  const result = new Int32Array(values.length)
  for (let x = 0; x < values.length; x++) {
    let value = values[x]!
    for (let offset = -radius; offset <= radius; offset++) {
      const at = x + offset
      if (at >= 0 && at < values.length) value = pick(value, values[at]!)
    }
    result[x] = value
  }
  return result
}

function skylineWithoutThinSpikesAndNotches(skyline: Int32Array, width: number) {
  const radius = Math.max(3, Math.round(width * 0.012))
  const withoutSpikes = slidingExtreme(slidingExtreme(skyline, radius, Math.max), radius, Math.min)
  const withoutNotches = slidingExtreme(slidingExtreme(skyline, radius, Math.min), radius, Math.max)
  return { withoutSpikes, withoutNotches }
}

// Spec: a cloud's edges are soft; a lattice, a crane, a mast or a cornice has strong, crisp ones. A pixel on such an edge
// that isn't unmistakably sky-coloured stays foreground wherever the skyline runs, so thin things against the sky stay.
const strongEdge = 0.4
const bandLikelihood = 0.65
const bandColour = 0.5

function turnFloatingSpecksIntoSky(
  hard: Float32Array,
  grounded: (x: number, y: number) => boolean,
  width: number,
  area: number,
) {
  const height = hard.length / width
  const seen = new Uint8Array(hard.length)
  const stack: number[] = []
  const patch: number[] = []
  for (let start = 0; start < hard.length; start++) {
    if (seen[start] || hard[start] !== 0) continue
    seen[start] = 1
    stack.push(start)
    patch.length = 0
    let touchesGround = false
    while (stack.length > 0) {
      const at = stack.pop()!
      patch.push(at)
      const x = at % width
      const y = (at - x) / width
      if (!touchesGround && grounded(x, y)) touchesGround = true
      if (touchesGround && patch.length > area) continue
      for (const next of [at - 1, at + 1, at - width, at + width]) {
        if (next < 0 || next >= hard.length || seen[next] || hard[next] !== 0) continue
        if ((next === at - 1 && x === 0) || (next === at + 1 && x === width - 1)) continue
        seen[next] = 1
        stack.push(next)
      }
    }
    if (!touchesGround && patch.length < area && height > 0) for (const at of patch) hard[at] = 1
  }
}

/** The finder a few rows or columns per step, so a caller can yield to the page between them; it returns the mask. */
function* findSkySteps(pixels: Pixels): Steps<SkyMask> {
  const { width, height } = pixels
  const first = yield* skyLikelihoodSteps(pixels)
  const edges = yield* boxBlur(first.vertical, width, height, 1)
  const straight = straightEdges(first.vertical, width, height)
  yield
  const roughSkyline = yield* skylineByDynamicProgramming(first.likelihood, edges, straight, width, height)
  const { likelihood, colour, structure } = yield* skyLikelihoodSteps(pixels, coloursAbove(pixels, roughSkyline))
  const skylineRows = yield* skylineByDynamicProgramming(likelihood, edges, straight, width, height)
  yield
  const lowestBand = [...skylineRows].toSorted((a, b) => a - b)[Math.floor(width * 0.85)] ?? height
  const { withoutSpikes, withoutNotches } = skylineWithoutThinSpikesAndNotches(skylineRows, width)
  const hard = new Float32Array(width * height)
  for (let x = 0; x < width; x++) {
    if (x % columnsPerStep === 0) yield
    const decidedByPixelFrom = Math.min(skylineRows[x]!, withoutNotches[x]!)
    const decidedByPixelTo = Math.max(skylineRows[x]!, withoutSpikes[x]!)
    for (let y = 0; y < height; y++) {
      const at = y * width + x
      const plainSky = structure[at]! < 0.5 || colour[at]! > holeColour
      if (y < decidedByPixelFrom) hard[at] = likelihood[at]! > foregroundLikelihood && plainSky ? 1 : 0
      else if (y < decidedByPixelTo) {
        hard[at] = (likelihood[at]! > bandLikelihood || colour[at]! > bandColour) && structure[at]! < 0.5 ? 1 : 0
      } else hard[at] = y < lowestBand && colour[at]! > holeColour ? 1 : 0
    }
  }
  turnFloatingSpecksIntoSky(
    hard,
    (x, y) => y >= Math.max(skylineRows[x]!, withoutSpikes[x]!),
    width,
    Math.round(width * height * 0.0004),
  )
  yield
  const soft = yield* boxBlur(hard, width, height, featherRadius)
  const alpha = new Uint8ClampedArray(width * height)
  for (let index = 0; index < alpha.length; index++) alpha[index] = Math.round(soft[index]! * 255)
  const skyline = Float32Array.from(skylineRows, (row) => row / height)
  const sorted = skyline.toSorted((a, b) => a - b)
  const horizon = sorted[Math.floor(sorted.length * 0.85)] ?? 0.5
  return { width, height, alpha, skyline, horizon }
}

/**
 * Finds the sky in a photo's pixels (RGBA, at most `skyMaskSize` on the long side) in one go, for a worker or a test:
 * a skyline per column from two passes, the second with sky colours learnt from the first; sky seen through gaps
 * below it (a lattice tower, branches) and objects standing above it (a mast) kept apart; then feathered.
 */
function findSky(pixels: Pixels): SkyMask {
  return finished(findSkySteps(pixels))
}

export { findSky, findSkySteps, skyLikelihood, skyMaskSize }
export type { Pixels, Rgb, SkyMask }

/** How a photo looks out at the sky: where the lens pointed and how wide it saw. */
type SkyPhotoView = {
  /** The compass heading of the photo's centre, in degrees clockwise from north. */
  heading: number
  /** The horizontal field of view in degrees. */
  fov: number
  /** Where the true horizon (0° altitude) crosses the photo's centre, from 0 (top) to 1 (bottom). */
  horizon: number
  /** The photo's width over its height. */
  aspect: number
}

/** A point on the photo, from 0 to 1 across and down; outside that range it is off the frame. */
type SkyPhotoPoint = { x: number; y: number; behind: boolean }

const radians = Math.PI / 180
const degrees = 180 / Math.PI
const fullFrameDiagonal = Math.hypot(36, 24)

/** The field of view a phone without focal data most likely has: a 26 mm equivalent main camera. */
const defaultSkyPhotoFov = 69

/**
 * The horizontal field of view of a photo from its 35 mm equivalent focal length, which is defined on the diagonal,
 * so it holds for any sensor shape.
 */
function fovFromFocalLength35mm(focalLength35mm: number, aspect: number) {
  const width = (fullFrameDiagonal * aspect) / Math.hypot(aspect, 1)
  return 2 * Math.atan(width / (2 * focalLength35mm)) * degrees
}

const wrapDegrees = (value: number) => (((value % 360) + 540) % 360) - 180

function lensOf(view: SkyPhotoView) {
  const focal = 0.5 / Math.tan((view.fov * radians) / 2)
  const pitch = Math.atan((view.horizon - 0.5) / view.aspect / focal)
  return { focal, pitch }
}

/**
 * Projects a direction in the sky, `azimuth` clockwise from north and `altitude` above the horizon, onto a
 * rectilinear photo. `behind` is true when the direction is behind the camera; x and y are then meaningless.
 */
function projectSky(view: SkyPhotoView, azimuth: number, altitude: number): SkyPhotoPoint {
  const { focal, pitch } = lensOf(view)
  const relative = wrapDegrees(azimuth - view.heading) * radians
  const up = altitude * radians
  const right = Math.cos(up) * Math.sin(relative)
  const height = Math.sin(up)
  const ahead = Math.cos(up) * Math.cos(relative)
  const cameraUp = height * Math.cos(pitch) - ahead * Math.sin(pitch)
  const cameraAhead = height * Math.sin(pitch) + ahead * Math.cos(pitch)
  if (cameraAhead <= 1e-6) return { x: Number.NaN, y: Number.NaN, behind: true }
  return {
    x: 0.5 + (focal * right) / cameraAhead,
    y: 0.5 - ((focal * cameraUp) / cameraAhead) * view.aspect,
    behind: false,
  }
}

/** The sky direction a point of the photo looks at: the inverse of `projectSky`. */
function unprojectSky(view: SkyPhotoView, x: number, y: number) {
  const { focal, pitch } = lensOf(view)
  const right = x - 0.5
  const cameraUp = (0.5 - y) / view.aspect
  const cameraAhead = focal
  const height = cameraUp * Math.cos(pitch) + cameraAhead * Math.sin(pitch)
  const ahead = -cameraUp * Math.sin(pitch) + cameraAhead * Math.cos(pitch)
  const azimuth = (view.heading + Math.atan2(right, ahead) * degrees + 360) % 360
  const altitude = Math.atan2(height, Math.hypot(right, ahead)) * degrees
  return { azimuth, altitude }
}

/**
 * Turns and tilts a view so a known sky direction, the sun at the photo's capture time, lands on the point a person
 * marked: the heading and the horizon that make it so, keeping the field of view.
 */
function calibrateSkyView(
  view: Pick<SkyPhotoView, "fov" | "aspect">,
  sun: { azimuth: number; altitude: number },
  marked: { x: number; y: number },
): Pick<SkyPhotoView, "heading" | "horizon"> {
  const focal = 0.5 / Math.tan((view.fov * radians) / 2)
  const right = marked.x - 0.5
  const cameraUp = (0.5 - marked.y) / view.aspect
  const elevationAt = (pitch: number) => {
    const height = cameraUp * Math.cos(pitch) + focal * Math.sin(pitch)
    const ahead = -cameraUp * Math.sin(pitch) + focal * Math.cos(pitch)
    return Math.atan2(height, Math.hypot(right, ahead))
  }
  let low = -80 * radians
  let high = 80 * radians
  for (let step = 0; step < 48; step++) {
    const middle = (low + high) / 2
    if (elevationAt(middle) < sun.altitude * radians) low = middle
    else high = middle
  }
  const pitch = (low + high) / 2
  const horizon = 0.5 + Math.tan(pitch) * focal * view.aspect
  const ahead = -cameraUp * Math.sin(pitch) + focal * Math.cos(pitch)
  const heading = (((sun.azimuth - Math.atan2(right, ahead) * degrees) % 360) + 360) % 360
  return { heading, horizon }
}

export { calibrateSkyView, defaultSkyPhotoFov, fovFromFocalLength35mm, projectSky, unprojectSky }
export type { SkyPhotoPoint, SkyPhotoView }

import type { Pixels, SkyMask } from "@/lib/sky-photo-mask"

/**
 * A photo's own clouds as two alpha maps over the sky, at the mask's size: `shade` is how much cloud covers each
 * pixel, and `light` how much of it is lit. Drawn as a dark layer under a lit one, they rebuild the clouds in any
 * colour of light.
 */
type SkyClouds = { width: number; height: number; shade: Uint8ClampedArray; light: Uint8ClampedArray }

/** The photo's windows that could be lit, as a glow alpha map at the mask's size, and how many it found and lit. */
type SkyWindows = { width: number; height: number; glow: Uint8ClampedArray; found: number; lit: number }

const clamp01 = (value: number) => (value < 0 ? 0 : value > 1 ? 1 : value)

function channels(data: Uint8ClampedArray, at: number) {
  const red = data[at]! / 255
  const green = data[at + 1]! / 255
  const blue = data[at + 2]! / 255
  const max = Math.max(red, green, blue)
  const min = Math.min(red, green, blue)
  return {
    red,
    green,
    blue,
    saturation: max === 0 ? 0 : (max - min) / max,
    light: 0.299 * red + 0.587 * green + 0.114 * blue,
  }
}

/**
 * Finds the clouds in the photo's sky: the less saturated a sky pixel is than the clearest blue in the photo, the more
 * cloud it is. Its brightness says how lit that cloud is.
 */
function findClouds({ data, width, height }: Pixels, mask: SkyMask): SkyClouds {
  let clearest = 0.15
  for (let index = 0; index < width * height; index++) {
    if (mask.alpha[index]! < 250) continue
    const { saturation, red, blue } = channels(data, index * 4)
    if (blue > red) clearest = Math.max(clearest, saturation)
  }
  const shade = new Uint8ClampedArray(width * height)
  const light = new Uint8ClampedArray(width * height)
  for (let index = 0; index < shade.length; index++) {
    const sky = mask.alpha[index]! / 255
    if (sky === 0) continue
    const { saturation, light: brightness } = channels(data, index * 4)
    const cloud = clamp01((1 - saturation / clearest - 0.15) * 1.6) * sky
    shade[index] = Math.round(cloud * 0.9 * 255)
    light[index] = Math.round(cloud * clamp01(brightness * 1.15) * 255)
  }
  return { width, height, shade, light }
}

function seeded(seed: number) {
  let state = seed | 0
  return () => {
    state = (state + 0x6d2b79f5) | 0
    let t = Math.imul(state ^ (state >>> 15), 1 | state)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4_294_967_296
  }
}

function localMean(values: Float32Array, width: number, height: number, radius: number) {
  const sums = new Float64Array((width + 1) * (height + 1))
  for (let y = 0; y < height; y++) {
    let row = 0
    for (let x = 0; x < width; x++) {
      row += values[y * width + x]!
      sums[(y + 1) * (width + 1) + x + 1] = sums[y * (width + 1) + x + 1]! + row
    }
  }
  const mean = new Float32Array(values.length)
  for (let y = 0; y < height; y++) {
    const top = Math.max(0, y - radius)
    const bottom = Math.min(height, y + radius + 1)
    for (let x = 0; x < width; x++) {
      const left = Math.max(0, x - radius)
      const right = Math.min(width, x + radius + 1)
      const total =
        sums[bottom * (width + 1) + right]! -
        sums[top * (width + 1) + right]! -
        sums[bottom * (width + 1) + left]! +
        sums[top * (width + 1) + left]!
      mean[y * width + x] = total / ((bottom - top) * (right - left))
    }
  }
  return mean
}

type Blob = { left: number; top: number; right: number; bottom: number; area: number }

const isVegetation = (red: number, green: number, blue: number) =>
  (green > red * 1.04 && green > blue * 1.04) || (red > blue * 1.35 && red - blue > 0.12 && green > blue * 1.15)

/**
 * Finds window-like panes on the buildings: small, nearly rectangular patches darker than a light, plain wall around
 * them, not foliage, each in a grid with a neighbour in its row and one in its column. A seeded share is drawn as glow.
 */
function findWindows({ data, width, height }: Pixels, mask: SkyMask, { share = 0.28, seed = 7 } = {}): SkyWindows {
  const light = new Float32Array(width * height)
  const wall = new Uint8Array(width * height)
  const plaster = new Uint8Array(width * height)
  for (let index = 0; index < light.length; index++) {
    const { red, green, blue, saturation, light: brightness } = channels(data, index * 4)
    light[index] = brightness
    wall[index] = mask.alpha[index]! < 40 && !isVegetation(red, green, blue) ? 1 : 0
    plaster[index] = wall[index] && saturation < 0.28 && brightness > 0.42 ? 1 : 0
  }
  const mean = localMean(light, width, height, Math.max(3, Math.round(width / 170)))
  const candidate = new Uint8Array(width * height)
  for (let index = 0; index < light.length; index++) {
    if (wall[index] && light[index]! < mean[index]! - 0.07 && light[index]! < 0.7) candidate[index] = 1
  }
  const onWall = (blob: Blob) => {
    let ring = 0
    let wallCount = 0
    for (let y = blob.top - 2; y <= blob.bottom + 2; y++) {
      for (let x = blob.left - 2; x <= blob.right + 2; x++) {
        const inside = y >= blob.top && y <= blob.bottom && x >= blob.left && x <= blob.right
        if (inside || x < 0 || y < 0 || x >= width || y >= height) continue
        ring++
        wallCount += plaster[y * width + x]!
      }
    }
    return ring > 0 && wallCount / ring > 0.6
  }
  const seen = new Uint8Array(width * height)
  const blobs: Blob[] = []
  const stack: number[] = []
  const maxArea = Math.max(24, Math.round((width * height) / 9000))
  for (let start = 0; start < candidate.length; start++) {
    if (!candidate[start] || seen[start]) continue
    seen[start] = 1
    stack.push(start)
    const blob = { left: width, top: height, right: 0, bottom: 0, area: 0 }
    while (stack.length > 0) {
      const at = stack.pop()!
      const x = at % width
      const y = (at - x) / width
      blob.area++
      blob.left = Math.min(blob.left, x)
      blob.right = Math.max(blob.right, x)
      blob.top = Math.min(blob.top, y)
      blob.bottom = Math.max(blob.bottom, y)
      for (const next of [at - 1, at + 1, at - width, at + width]) {
        if (next < 0 || next >= candidate.length || seen[next] || !candidate[next]) continue
        if ((next === at - 1 && x === 0) || (next === at + 1 && x === width - 1)) continue
        seen[next] = 1
        stack.push(next)
      }
    }
    const boxWidth = blob.right - blob.left + 1
    const boxHeight = blob.bottom - blob.top + 1
    const fill = blob.area / (boxWidth * boxHeight)
    const aspect = boxWidth / boxHeight
    if (blob.area >= 2 && blob.area <= maxArea && fill > 0.6 && aspect > 0.25 && aspect < 4 && onWall(blob))
      blobs.push(blob)
  }
  const reachOf = (blob: Blob) =>
    Math.max(6, Math.round(width / 60), 3 * Math.max(blob.right - blob.left + 1, blob.bottom - blob.top + 1))
  const inRow = (blob: Blob, other: Blob) =>
    other !== blob && Math.abs(other.top - blob.top) <= 1 && Math.abs(other.left - blob.left) <= reachOf(blob)
  const inColumn = (blob: Blob, other: Blob) =>
    other !== blob && Math.abs(other.left - blob.left) <= 1 && Math.abs(other.top - blob.top) <= reachOf(blob)
  const windows = blobs.filter(
    (blob) => blobs.some((other) => inRow(blob, other)) && blobs.some((other) => inColumn(blob, other)),
  )
  const random = seeded(seed)
  const glow = new Uint8ClampedArray(width * height)
  let lit = 0
  for (const window of windows) {
    if (random() > share) continue
    lit++
    const strength = Math.round((0.55 + random() * 0.45) * 255)
    for (let y = window.top; y <= window.bottom; y++) {
      for (let x = window.left; x <= window.right; x++) glow[y * width + x] = strength
    }
  }
  return { width, height, glow, found: windows.length, lit }
}

export { findClouds, findWindows }
export type { SkyClouds, SkyWindows }
